  function timeout(fn, ms) { const id = setTimeout(fn, ms); disposers.push(() => clearTimeout(id)); return id; }
  function safeDate(value, fallback = new Date()) { const date = value ? new Date(value) : fallback; return Number.isNaN(date.getTime()) ? fallback : date; }
  function formatDate(date, options) { try { return new Intl.DateTimeFormat(locale, { timeZone: timezone, ...options }).format(date); } catch { return new Intl.DateTimeFormat("zh-CN", options).format(date); } }
