    interval(()=>{$("worldList").innerHTML=zones.map(zone=>{const city=zone.split("/").pop().replaceAll("_"," ");const value=new Intl.DateTimeFormat(locale,{timeZone:zone,hour:"2-digit",minute:"2-digit",hour12:false}).format(new Date());const day=new Intl.DateTimeFormat(locale,{timeZone:zone,weekday:"short"}).format(new Date());return `<div class="world-row"><span>${esc(city)}</span><small>${esc(day)}</small><strong>${value}</strong></div>`}).join("");},1000);
