  function renderUnitConverter() {
    const configs={length:[["米",1],["千米",1000],["英尺",.3048],["英里",1609.344]],weight:[["千克",1],["克",.001],["磅",.453592],["盎司",.0283495]],temperature:[["摄氏",1],["华氏",1],["开尔文",1]]};const kind=p("unitType","length"),units=configs[kind];setWidget(`<p class="kicker">UNIT CONVERTER · ${kind.toUpperCase()}</p><div class="converter-grid"><label>数值<input id="convertInput" value="1" type="number"></label><span>⇄</span><label>结果<input id="convertOutput" readonly></label><label><select id="unitFrom">${units.map((u,i)=>`<option value="${i}">${u[0]}</option>`).join("")}</select></label><span></span><label><select id="unitTo">${units.map((u,i)=>`<option value="${i}" ${i===1?"selected":""}>${u[0]}</option>`).join("")}</select></label></div>`);const draw=()=>{const value=Number($("convertInput").value),from=Number($("unitFrom").value),to=Number($("unitTo").value);let result;if(kind==="temperature"){let c=from===0?value:from===1?(value-32)*5/9:value-273.15;result=to===0?c:to===1?c*9/5+32:c+273.15;}else result=value*units[from][1]/units[to][1];$("convertOutput").value=Number(result.toFixed(4));};["convertInput","unitFrom","unitTo"].forEach(id=>$(id).oninput=draw);draw();
  }
