  function renderBMI() { setWidget(`<p class="kicker">BMI CALCULATOR</p><div class="tool-form"><input class="tool-input" id="bmiWeight" type="number" value="60" placeholder="体重"><input class="tool-input" id="bmiHeight" type="number" value="170" placeholder="身高"><div class="result-box" id="bmiResult"></div></div>`);const draw=()=>{const metric=p("units","metric")==="metric",w=Number($("bmiWeight").value),h=Number($("bmiHeight").value),bmi=metric?w/(h/100)**2:w/h**2*703;$("bmiResult").textContent=`BMI ${bmi.toFixed(1)} · ${bmi<18.5?"偏轻":bmi<24?"健康范围":bmi<28?"偏高":"较高"}`;};["bmiWeight","bmiHeight"].forEach(id=>$(id).oninput=draw);draw(); }
  function renderAge() { const birth=safeDate(p("birthday","2000-01-01")),now=new Date(),years=now.getFullYear()-birth.getFullYear()-(now<new Date(now.getFullYear(),birth.getMonth(),birth.getDate())?1:0),next=new Date(now.getFullYear(),birth.getMonth(),birth.getDate());if(next<now)next.setFullYear(next.getFullYear()+1);setWidget(`<p class="kicker">AGE CALCULATOR</p><div class="big-number mono">${years}</div><h2 class="title">岁</h2><p class="caption muted">距离下次生日还有 ${Math.ceil((next-now)/864e5)} 天</p>`); }
