  function renderPassword() { const length=n("length",16),chars=`ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789${b("symbols",true)?"!@#$%&*+-=?":""}`;setWidget(`<p class="kicker">PASSWORD GENERATOR</p><div class="copy-card mono" id="passwordValue"></div><div class="button-row"><button class="action" id="passwordNew">重新生成</button><button class="action secondary" id="passwordCopy">复制</button></div>`);const draw=()=>{$("passwordValue").textContent=Array.from(crypto.getRandomValues(new Uint32Array(length)),x=>chars[x%chars.length]).join("");};$("passwordNew").onclick=draw;$("passwordCopy").onclick=()=>navigator.clipboard?.writeText($("passwordValue").textContent);draw(); }
