  function renderScenicQuote(){const daily=[["Art enables us to find ourselves and lose ourselves at the same time.","Thomas Merton"],["The details are not the details. They make the design.","Charles Eames"],["There is a crack in everything. That’s how the light gets in.","Leonard Cohen"],["Simplicity is the ultimate sophistication.","Leonardo da Vinci"]],rand=seeded(dateId()+"scenic-quote"),picked=daily[Math.floor(rand()*daily.length)],quote=p("quoteSource","daily")==="daily"?picked:[p("quote","Art enables us to find ourselves and lose ourselves at the same time."),p("author","Thomas Merton")],image=mediaUrl(p("backgroundUrl","https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=85")),overlay=Math.max(0,Math.min(85,Number(p("overlay","42"))))/100,blur=Math.max(0,Math.min(16,Number(p("imageBlur","0"))));setWidget(`<div class="scenic-bg" style="--image-blur:${blur}px">${image?`<img src="${esc(image)}" alt="">`:""}</div><div class="scenic-shade" style="--shade:${overlay}"></div><div class="scenic-copy scenic-${esc(p("quotePosition","bottom"))}"><span>❝</span><blockquote>${esc(quote[0])}</blockquote><cite>— ${esc(quote[1])}</cite></div>`,"media-widget scenic-widget");}
  function renderAmbientMixer(){const sounds=[["rain","雨声","☂",p("rainUrl"),Number(p("rainVolume","65"))],["cafe","咖啡馆","☕︎",p("cafeUrl"),Number(p("cafeVolume","25"))],["fire","篝火","✦",p("fireUrl"),Number(p("fireVolume","35"))]];setWidget(`<p class="kicker">AMBIENT SOUNDSCAPE</p><div class="calendar-head"><strong>${esc(p("title","Rainy Reading Room"))}</strong><span class="pill" id="ambientStatus">选择声音开始</span></div><div class="ambient-grid">${sounds.map(([id,label,icon,url,volume])=>`<div class="ambient-channel"><button data-ambient="${id}"><i>${icon}</i><b>${label}</b><span>▶</span></button><input data-ambient-volume="${id}" aria-label="${label}音量" type="range" min="0" max="100" value="${Math.max(0,Math.min(100,volume))}"><audio id="ambient-${id}" loop preload="none" ${mediaUrl(url)?`src="${esc(mediaUrl(url))}"`:""}></audio></div>`).join("")}</div><p class="caption muted">可分别填写三个公开音频直链，并自由叠加音量。</p>`,"media-widget ambient-widget");root.querySelectorAll("[data-ambient]").forEach(button=>button.onclick=()=>{const audio=$(`ambient-${button.dataset.ambient}`);if(!audio.src){$("ambientStatus").textContent="请先填写这个声音的音频链接";return;}if(audio.paused){audio.play().then(()=>{button.classList.add("is-active");button.querySelector("span").textContent="❚❚";$("ambientStatus").textContent="正在混合氛围";}).catch(()=>{$("ambientStatus").textContent="音频链接无法播放";});}else{audio.pause();button.classList.remove("is-active");button.querySelector("span").textContent="▶";}});root.querySelectorAll("[data-ambient-volume]").forEach(input=>{const audio=$(`ambient-${input.dataset.ambientVolume}`);audio.volume=Number(input.value)/100;input.oninput=()=>{audio.volume=Number(input.value)/100;};});disposers.push(()=>sounds.forEach(([id])=>$(`ambient-${id}`)?.pause()));}
  function renderLyricCard(){const rows=p("lyricLines","Stay with the quiet light|留在安静的光里\nLet every small moment sing|让每一个微小瞬间歌唱\nWe are here, and that is enough|此刻在这里，已经足够").split("\n").filter(Boolean).map(line=>line.split("|")),motion=p("typeMotion","fade");let current=0;setWidget(`<p class="kicker">LYRIC STUDY · ${esc(p("artist","Your Playlist"))}</p><h2 class="title">${esc(p("songTitle","Night Letters"))}</h2><button class="lyric-stage motion-${esc(motion)}" id="lyricStage"><span id="lyricOriginal"></span><small id="lyricTranslation"></small><i id="lyricCount"></i></button>`,"media-widget lyric-widget");const draw=()=>{const row=rows[current]||["…",""];$("lyricStage").classList.remove("is-changing");void $("lyricStage").offsetWidth;$("lyricStage").classList.add("is-changing");$("lyricOriginal").textContent=row[0];$("lyricTranslation").textContent=b("showTranslation",true)?row[1]||"":"";$("lyricCount").textContent=`${String(current+1).padStart(2,"0")} / ${String(rows.length).padStart(2,"0")}`;};$("lyricStage").onclick=()=>{current=(current+1)%rows.length;draw();};draw();if(b("autoAdvance",true)){const id=setInterval(()=>$("lyricStage").click(),Math.max(2,n("lineInterval",5))*1000);disposers.push(()=>clearInterval(id));}}
